import { allVariables, variablesFor } from './load.js';
import { GROUPS, type AnyVarDef, type Scope } from './types.js';

/**
 * Everything written about configuration is generated from the registry, so none of it can drift
 * (ADR-0044). `scripts/generate.ts` writes these to disk (`pnpm config:docs`) and CI re-generates
 * them and fails if a committed file differs (`pnpm config:check`).
 *
 * Pure functions of the registry: no file or environment access.
 */

export type Profile = 'local' | 'staging' | 'production';

const GENERATED = [
  '# GENERATED by `pnpm config:docs` from packages/env/src/registry.ts.',
  '# Do not edit by hand: change the registry and regenerate. CI fails if this file is stale.',
];

/** The compose example reads these; they are release plumbing, not application configuration. */
const COMPOSE_BLOCK = [
  '# ---- Release and addresses (read by docker-compose, deploy/docker-compose.prod.example.yml) -----',
  'CRM_REGISTRY=registry.example.com/acme',
  'CRM_VERSION=0.0.0',
  'APP_HOST=app.example.com',
  'API_HOST=api.example.com',
  '',
];

const firstScope = (def: AnyVarDef): Scope => def.scopes[0] ?? 'api';

function wrap(text: string, width: number, prefix: string): string[] {
  const lines: string[] = [];
  let line = '';
  for (const word of text.split(/\s+/)) {
    if (line !== '' && (prefix + line + ' ' + word).length > width) {
      lines.push(prefix + line);
      line = word;
    } else {
      line = line === '' ? word : `${line} ${word}`;
    }
  }
  if (line !== '') lines.push(prefix + line);
  return lines;
}

function facts(def: AnyVarDef): string {
  const parts = [`Used by: ${def.scopes.join(', ')}`];
  parts.push(
    def.requirement === 'required'
      ? 'Required'
      : def.requirement === 'production'
        ? 'Required in production'
        : 'Optional',
  );
  if (def.secret) parts.push('SECRET');
  const fallback = def.defaultFor(firstScope(def));
  if (fallback !== undefined) parts.push(`Default: ${fallback}`);
  if (def.values !== undefined) parts.push(`One of: ${def.values.join(' | ')}`);
  return parts.join('. ') + '.';
}

function valueFor(name: string, def: AnyVarDef, profile: Profile): string {
  if (name === 'NODE_ENV') return profile === 'local' ? 'development' : 'production';
  if (name === 'APP_ENV') return profile;
  if (profile === 'local') return def.local ?? def.defaultFor(firstScope(def)) ?? '';
  // A secret is never given a plausible-looking value in a template someone will copy.
  return def.example ?? (def.secret ? '' : (def.defaultFor(firstScope(def)) ?? ''));
}

/** `.env.example` (local) and the staging and production templates. */
export function renderEnvExample(profile: Profile): string {
  const out: string[] = [...GENERATED, '#'];
  if (profile === 'local') {
    out.push(
      '# Copy to .env for local development. NEVER commit .env (CLAUDE.md §5.8).',
      '# Every value here is a throwaway local-development placeholder.',
    );
  } else {
    out.push(
      `# ${profile === 'staging' ? 'Staging' : 'Production'} template. Copy to deploy/${profile}.env (git ignores it) and fill in every`,
      '# value; set them as secrets on the platform instead where you can. NEVER commit real values.',
      '# Use separate secrets and a separate database from every other environment: nothing is shared.',
      '# The API and the worker refuse to start in production with a development value, and say which',
      '# variable is wrong (never its value).',
      '#',
      // Generated from the registry, so it cannot fall behind it: the web app is registered for
      // these and no others, and refuses to start if given a secret that belongs to another process.
      ...wrap(
        `The web app (Vercel) takes ONLY: ${variablesFor('web')
          .map(([name]) => name)
          .join(', ')}. It refuses to start if given any secret below. See docs/CONFIGURATION.md.`,
        100,
        '# ',
      ),
    );
  }
  out.push('');
  if (profile !== 'local') out.push(...COMPOSE_BLOCK);

  for (const group of GROUPS) {
    const members = allVariables().filter(
      ([, def]) => def.group === group.id && !(profile !== 'local' && group.id === 'tooling'),
    );
    if (members.length === 0) continue;
    out.push(`# ===== ${group.title} ${'='.repeat(Math.max(3, 72 - group.title.length))}`);
    out.push(...wrap(group.blurb, 100, '# '), '');

    for (const [name, def] of members) {
      out.push(...wrap(def.description, 100, '# '));
      out.push(...wrap(facts(def), 100, '# '));
      if (def.obtain !== undefined) out.push(...wrap(`Get it: ${def.obtain}`, 100, '# '));
      if (def.note !== undefined) out.push(...wrap(def.note, 100, '# '));
      const value = valueFor(name, def, profile);
      // Anything that may be left blank and has no value to show is written commented out.
      const commented = def.requirement === 'optional' && value === '';
      out.push(`${commented ? '# ' : ''}${name}=${value}`, '');
    }
  }
  return out.join('\n').replace(/\n+$/, '\n');
}

function code(text: string): string {
  return `\`${text}\``;
}

/** `docs/CONFIGURATION.md`. */
export function renderConfigurationMd(): string {
  const vars = allVariables();
  const out: string[] = [
    '<!-- GENERATED by `pnpm config:docs` from packages/env/src/registry.ts. Do not edit by hand: change the registry and regenerate. CI fails if this file is stale. -->',
    '',
    '# Configuration',
    '',
    'Every environment variable the system reads, who reads it, what it is for, and where to get a real',
    'value. This page, `.env.example` and the staging and production templates are generated from one',
    'registry, [`packages/env/src/registry.ts`](../packages/env/src/registry.ts), so they cannot disagree',
    'with the code. See [ADR-0044](adr/0044-configuration-registry.md) for why.',
    '',
    '## How configuration works',
    '',
    '- **One place declares each variable** (its type, default, whether it is secret, where to get it).',
    '  **One place reads the environment**: `packages/env`. Nothing else in the application touches',
    '  `process.env`, and an ESLint rule fails the build if it does.',
    '- **Each process loads only its own variables** (`api`, `worker`, `web`, `db` for the CLI scripts).',
    '  The type of its environment is computed from the registry, so the web app cannot even name',
    '  `DATABASE_URL`.',
    '- **It fails fast.** A process validates its environment before it listens and refuses to start,',
    '  listing every problem at once. A message names the variable and never repeats a secret.',
    '- **A variable set to an empty string is not set.** `FOO=` in an env file, an empty platform field',
    '  and compose\'s `${FOO:-}` all mean "use the default, or leave it off".',
    '- **Production is stricter.** With `NODE_ENV=production` the API and the worker also refuse a',
    '  development value: a placeholder secret, `console` email, `http` or `localhost` URLs, the database',
    '  superuser or an administrative role (rules in `packages/core/src/config/production.ts`, ADR-0041).',
    '- **The web app holds no credential.** Outside local development it refuses to start if it is given',
    '  any secret that belongs to another process (a database URL, `AUTH_SECRET`, an object-storage key).',
    '',
    '## Environments',
    '',
    '| `APP_ENV`    | `NODE_ENV`    | Template                                       | Notes                                                |',
    '| ------------ | ------------- | ---------------------------------------------- | ---------------------------------------------------- |',
    '| `local`      | `development` | [`.env.example`](../.env.example)              | Throwaway values; `pnpm infra:up` provides the services. |',
    '| `staging`    | `production`  | [`deploy/staging.env.example`](../deploy/staging.env.example) | As production, with its own secrets and database. |',
    '| `production` | `production`  | [`deploy/production.env.example`](../deploy/production.env.example) | Every secret generated, never reused.       |',
    '',
    '`APP_ENV` defaults to `production` when `NODE_ENV=production`, and to `local` otherwise, so set it to',
    '`staging` explicitly on a staging deployment. Values come from the process environment your platform',
    'provides; only the local CLI scripts also read a repository-root `.env`, and a variable already set',
    'always wins over the file.',
    '',
    '## All variables',
    '',
    '| Variable | Used by | Required | Secret |',
    '| -------- | ------- | -------- | ------ |',
  ];

  for (const [name, def] of vars) {
    const required =
      def.requirement === 'required'
        ? 'yes'
        : def.requirement === 'production'
          ? 'in production'
          : 'no';
    out.push(
      `| [${code(name)}](#${name.toLowerCase()}) | ${def.scopes.join(', ')} | ${required} | ${def.secret ? 'yes' : 'no'} |`,
    );
  }
  out.push('');

  for (const group of GROUPS) {
    const members = vars.filter(([, def]) => def.group === group.id);
    if (members.length === 0) continue;
    out.push(`## ${group.title}`, '', group.blurb, '');
    for (const [name, def] of members) {
      out.push(`### ${code(name)}`, '', def.description, '');
      const fallback = def.defaultFor(firstScope(def));
      const perScope = def.scopes
        .map((scope) => [scope, def.defaultFor(scope)] as const)
        .filter(([, value]) => value !== undefined);
      const differs = new Set(perScope.map(([, value]) => value)).size > 1;
      out.push(`- **Used by:** ${def.scopes.join(', ')}`);
      out.push(
        `- **Required:** ${
          def.requirement === 'required'
            ? 'yes: the process refuses to start without it'
            : def.requirement === 'production'
              ? 'in production (a production process refuses to run without a real value)'
              : 'no'
        }`,
      );
      out.push(
        `- **Secret:** ${def.secret ? 'yes: never logged, never committed, never on the web app' : 'no'}`,
      );
      if (fallback !== undefined) {
        out.push(
          `- **Default:** ${
            differs
              ? perScope.map(([scope, value]) => `${code(String(value))} (${scope})`).join(', ')
              : code(fallback === '' ? '(empty)' : fallback)
          }`,
        );
      }
      if (def.values !== undefined) out.push(`- **Values:** ${def.values.map(code).join(', ')}`);
      if (def.obtain !== undefined) out.push(`- **Where to get it:** ${def.obtain}`);
      if (def.note !== undefined) out.push('', def.note);
      out.push('');
    }
  }

  out.push(
    '## Adding or changing a variable',
    '',
    '1. Add it to [`packages/env/src/registry.ts`](../packages/env/src/registry.ts): the scopes that read it,',
    '   whether it is secret, its default, where to get it. Choosing the scopes is a security decision:',
    '   a variable is only validated and typed for the scopes it lists.',
    "2. Read it through `loadEnv(scope)` (the app's own `env` module does this). Never `process.env`.",
    '3. Run `pnpm config:docs` and commit what it regenerates (this page and the templates).',
    '4. If production must refuse some values of it, add the rule to `packages/core/src/config/production.ts`.',
    '',
    '`pnpm config:check` (run in CI) regenerates everything and fails if a committed file differs, and the',
    "registry's own tests fail if a variable documented as required is not, if a documented default is not",
    'the real one, if a credential is not marked secret, or if a secret is ever given to the web app.',
    '',
    '## Not covered here',
    '',
    'Developer tooling that is not part of the product reads a few variables of its own and is exempt from',
    'the rule above: the Playwright and Vitest configuration files, the screenshot script',
    "(`apps/web/scripts`), and the performance test row count. The load-test seed's `PERF_ADMIN_URL` is",
    'registered (scope `perf`) precisely so that no application scope can ever hold a superuser URL.',
    'The release variables `docker-compose` reads (`CRM_REGISTRY`, `CRM_VERSION`, `APP_HOST`,',
    '`API_HOST`) are in the production template; they are plumbing, not application configuration.',
    '',
  );
  return out.join('\n');
}
